-- Re-categorize existing official templates by the app's 8 mood types (情绪风格),
-- then add new official short + long templates so every mood has both.
-- All shots use the same editable schema as user-generated scripts, so loading a
-- template drops straight into the storyboard editor.

-- ── 1. Align existing templates' category with the app's mood taxonomy ──
UPDATE public.script_templates SET category = '治愈'
  WHERE is_official = true AND title IN ('雨后森林漫步', '一碗面的故事', '流浪猫日记', '那年夏天');
UPDATE public.script_templates SET category = '文艺'
  WHERE is_official = true AND title IN ('霓虹都市独白', '毕业那天', '一期一会');
UPDATE public.script_templates SET category = '史诗'
  WHERE is_official = true AND title IN ('太空行走');

