INSERT INTO public.script_templates (title, category, emoji, description, mood, duration_type, shots, is_official, created_by) VALUES
(
  '向阳面包店', '治愈', '🍞', '都市失意的女孩回到海边小镇，接手外婆留下的面包店，在麦香与人情中重新找回生活的温度。深度治愈长片。', 'healing', 'long',
  '[{"shotNumber":"01","shotType":"大远景","visual":"清晨的海边小镇全景，白墙红瓦，一辆长途巴士停在路口","duration":"7s","dialogue":"","audio":"海浪声、海鸥鸣叫","character":"","directorNote":"【第一幕·归来】航拍缓推建立地域感","emotionIntensity":25},{"shotNumber":"02","shotType":"中景","visual":"拖着行李箱的女孩站在一家落锁的旧面包店前，招牌褪色斑驳","duration":"6s","dialogue":"（旁白）外婆走后，这家店空了整整一年。","audio":"行李箱滚轮声、风铃轻响","character":"小满 — 二十六岁，刚辞掉城里的工作","directorNote":"逆光剪影，强调人与旧店的关系","emotionIntensity":40},{"shotNumber":"03","shotType":"特写","visual":"她推开门，灰尘在光柱中飞舞，墙上还贴着外婆手写的面包配方","duration":"5s","dialogue":"","audio":"门轴吱呀声、寂静","character":"","directorNote":"丁达尔光柱中的尘埃，怀旧氛围","emotionIntensity":55},{"shotNumber":"04","shotType":"中景","visual":"小满系上外婆的旧围裙笨拙揉面，第一炉却烤糊了，她沮丧坐下","duration":"6s","dialogue":"","audio":"烤箱计时器、一声叹息","character":"","directorNote":"【第二幕·重启】暖色厨房，失败的烟火气","emotionIntensity":45},{"shotNumber":"05","shotType":"近景","visual":"隔壁修船的老伯送来一筐海盐，说外婆的面包当年救过他的胃","duration":"6s","dialogue":"（老伯）你外婆说，面包要放一点海的味道。","audio":"木门推开声、爽朗笑声","character":"阿海伯 — 六十岁，镇上的老邻居","directorNote":"侧光人物，传递人情温度","emotionIntensity":60},{"shotNumber":"06","shotType":"中景","visual":"镇上孩子趴在橱窗外看小满烤面包，她笑着递出第一块成功的吐司","duration":"5s","dialogue":"（孩子）姐姐，好香！","audio":"孩子嬉笑、烤箱叮的一声","character":"镇上的孩子们","directorNote":"橱窗内外构图，玻璃上的哈气","emotionIntensity":70},{"shotNumber":"07","shotType":"特写","visual":"深夜，小满对照外婆的配方反复试验，面团终于发酵出理想的样子","duration":"5s","dialogue":"","audio":"座钟滴答、面团轻响","character":"","directorNote":"顶光俯拍双手，专注的仪式感","emotionIntensity":65},{"shotNumber":"08","shotType":"远景","visual":"重新开业那天，褪色招牌被擦亮，门口排起小小的队伍","duration":"6s","dialogue":"","audio":"风铃、人群低语、海浪","character":"","directorNote":"【第三幕·新生】固定机位，晨光中的小店","emotionIntensity":75},{"shotNumber":"09","shotType":"近景","visual":"小满把第一炉面包摆上货架，抬头看见墙上外婆的照片，轻声说话","duration":"5s","dialogue":"（轻声）外婆，我把店开回来了。","audio":"轻柔弦乐渐入","character":"","directorNote":"面部特写，眼里有光也有泪","emotionIntensity":85},{"shotNumber":"10","shotType":"大远景","visual":"黄昏小镇，面包店暖黄的灯亮着，麦香仿佛随海风飘向整条街","duration":"7s","dialogue":"（旁白）原来回家，是从揉好一块面团开始的。","audio":"弦乐渐强后归于海浪","character":"","directorNote":"航拍拉升，与开场呼应收尾","emotionIntensity":60}]'::jsonb,
