(
  '最后的旧书店', '文艺', '📖', '城市更新的浪潮中，一家即将拆迁的旧书店迎来最后七天，店主与读者们用各自的方式与时光告别。文艺长片。', 'literary', 'long',
  '[{"shotNumber":"01","shotType":"远景","visual":"老城区窄巷尽头，斑驳的旧书店亮着昏黄的灯，墙上贴着拆迁公告","duration":"7s","dialogue":"","audio":"城市远处车流、风吹纸张","character":"","directorNote":"【第一幕·告别通知】固定机位，纵深巷弄","emotionIntensity":30},{"shotNumber":"02","shotType":"中景","visual":"白发店主用抹布一本本擦拭书脊，动作缓慢而郑重","duration":"6s","dialogue":"（旁白）这家店，比我女儿的年纪还要大。","audio":"抹布摩擦声、老唱片机","character":"老周 — 七十岁，守店四十年","directorNote":"侧逆光，灰尘与时光感","emotionIntensity":45},{"shotNumber":"03","shotType":"特写","visual":"一封夹在旧书里的泛黄情书滑落，落款是几十年前的日期","duration":"5s","dialogue":"","audio":"纸张飘落声","character":"","directorNote":"微距对焦褪色字迹，留白想象","emotionIntensity":55},{"shotNumber":"04","shotType":"中景","visual":"一个女孩每天放学都来，蹲在角落读完同一套没钱买的小说","duration":"6s","dialogue":"（女孩）老板，我还差最后一本就读完了。","audio":"翻书声、巷口叫卖","character":"阿萤 — 十六岁，常来蹭书的学生","directorNote":"【第二幕·最后的读者】暖光，人物融入书架","emotionIntensity":50},{"shotNumber":"05","shotType":"近景","visual":"老周默默把那套书从货架取下，用牛皮纸包好放进女孩书包","duration":"5s","dialogue":"（老周）拿去吧，书要遇到读它的人才算活着。","audio":"牛皮纸窸窣声","character":"","directorNote":"双手特写，传递的仪式感","emotionIntensity":70},{"shotNumber":"06","shotType":"中景","visual":"老顾客们陆续赶来，有人朗读，有人合影，书店里第一次这样热闹","duration":"6s","dialogue":"","audio":"交谈声、笑声、翻书声交织","character":"老顾客们","directorNote":"中景群像，暖色调，人间烟火","emotionIntensity":65},{"shotNumber":"07","shotType":"特写","visual":"墙上的旧挂钟、读者留言本、外婆牌台灯，被镜头一一温柔抚过","duration":"6s","dialogue":"","audio":"钟摆声、笔尖书写声","character":"","directorNote":"一组空镜慢摇，凝视细节","emotionIntensity":60},{"shotNumber":"08","shotType":"中景","visual":"最后一夜，老周独自坐在书堆中，借着台灯读完那封泛黄的情书","duration":"6s","dialogue":"（旁白）原来每本书里，都藏着一个没说完的故事。","audio":"翻页声、窗外夜雨","character":"老周","directorNote":"【第三幕·熄灯】单人灯下构图，文学性凝视","emotionIntensity":80},{"shotNumber":"09","shotType":"近景","visual":"清晨，老周郑重地拉下卷帘门，把钥匙轻轻放进信箱","duration":"5s","dialogue":"","audio":"卷帘门金属声、钥匙落地","character":"","directorNote":"手部特写，告别的克制","emotionIntensity":75},{"shotNumber":"10","shotType":"大远景","visual":"巷口，女孩抱着那套书回头望了一眼，旧书店的灯永远地暗了下去","duration":"7s","dialogue":"（旁白）有些地方会消失，但它给过的光，会一直亮在某个人心里。","audio":"钢琴独奏渐弱、城市苏醒","character":"阿萤","directorNote":"固定长镜，让人物走出画面收尾","emotionIntensity":70}]'::jsonb,
  true, NULL
),
(
  '烽燧', '史诗', '⚔️', '大漠孤烟，一座边关烽火台上，最后三名戍卒在援军未至的绝境中，用生命点燃了那一束警示的狼烟。史诗长片。', 'epic', 'long',
  '[{"shotNumber":"01","shotType":"大远景","visual":"黄昏的戈壁大漠，一座孤零零的烽燧矗立在天地之间","duration":"7s","dialogue":"","audio":"呼啸的风沙、苍凉号角","character":"","directorNote":"【第一幕·孤燧】航拍极远景，人与天地的渺小","emotionIntensity":35},{"shotNumber":"02","shotType":"中景","visual":"烽火台上，老兵眺望远方扬起的沙尘，神色骤然凝重","duration":"6s","dialogue":"（老兵）来了，比探报说的还要快。","audio":"风声、铠甲碰撞","character":"校尉老秦 — 五十岁，戍边三十年","directorNote":"侧逆光剪影，凝视的力量","emotionIntensity":50},{"shotNumber":"03","shotType":"近景","visual":"年轻戍卒的手紧握长戈，指节发白，眼里有恐惧也有倔强","duration":"5s","dialogue":"（年轻戍卒）校尉，援军……还有多久？","audio":"心跳、远处隐约马蹄","character":"戍卒阿木 — 十九岁，第一次上战场","directorNote":"极浅景深，恐惧与勇气并存","emotionIntensity":55},{"shotNumber":"04","shotType":"远景","visual":"地平线上，黑压压的骑兵如潮水般漫过沙丘，遮天蔽日","duration":"6s","dialogue":"","audio":"雷鸣般的马蹄、号角骤起","character":"","directorNote":"【第二幕·绝境】大广角展现压倒性兵力","emotionIntensity":70},{"shotNumber":"05","shotType":"中景","visual":"老秦将最后一捆狼烟柴草搬上燧顶，三人合力点燃火种","duration":"6s","dialogue":"（老秦）只要这把火点起来，三百里外就知道敌人来了。","audio":"柴草噼啪、风助火势","character":"三名戍卒","directorNote":"火光映脸，仰拍英雄群像","emotionIntensity":75},{"shotNumber":"06","shotType":"特写","visual":"火把凑近柴草的瞬间，狼烟腾空而起，笔直冲入苍穹","duration":"5s","dialogue":"","audio":"烈焰轰燃、号角长鸣","character":"","directorNote":"仰拍狼烟直上，全片视觉支点","emotionIntensity":85},{"shotNumber":"07","shotType":"中景","visual":"敌骑攻上燧台，三人背靠背挥戈死战，以一当十","duration":"6s","dialogue":"（阿木嘶吼）烽火不能灭！","audio":"兵刃相击、嘶吼、风声","character":"三名戍卒","directorNote":"手持跟拍混战，尘土与火光","emotionIntensity":90},{"shotNumber":"08","shotType":"近景","visual":"老秦身中数箭仍死守烽火，回头看了一眼那束不灭的狼烟，欣慰一笑","duration":"5s","dialogue":"（老秦）值了。","audio":"战声渐远、风声呜咽","character":"校尉老秦","directorNote":"【第三幕·不灭】慢镜特写，悲壮的微笑","emotionIntensity":95},{"shotNumber":"09","shotType":"大远景","visual":"夕阳下，烽燧之上狼烟未断，远方天际终于扬起己方援军的旌旗","duration":"7s","dialogue":"（旁白）他们没能等到援军，但援军，因这束烟而来。","audio":"苍凉而恢宏的交响、马蹄渐近","character":"","directorNote":"极远景对比，烟与旗的呼应","emotionIntensity":90},{"shotNumber":"10","shotType":"特写","visual":"战后焦土上，半截染血的长戈插在沙中，狼烟的余烬随风飘散","duration":"6s","dialogue":"（旁白）大漠记得每一个，没有留下名字的人。","audio":"风沙、余烬声、号角余韵","character":"","directorNote":"固定机位空镜，让历史归于沉默","emotionIntensity":70}]'::jsonb,
  true, NULL
),
(
  '五个室友的战争', '搞笑', '😄', '五个性格迥异的年轻人挤在一间老破租房里，从抢厕所到分摊水电，一地鸡毛却笑料百出的都市合租情景喜剧。', 'funny', 'long',
  '[{"shotNumber":"01","shotType":"远景","visual":"老旧居民楼内一间贴满便利贴的合租房，五扇门同时打开又关上","duration":"5s","dialogue":"","audio":"五扇门此起彼伏的开关声、闹钟交响","character":"","directorNote":"【第一幕·早高峰】固定机位看五门齐动，节奏喜感","emotionIntensity":45},{"shotNumber":"02","shotType":"中景","visual":"五人在唯一的卫生间门口排成长队，各自憋着姿势焦躁跳脚","duration":"5s","dialogue":"（程序员）求求了快一点，我九点的会！","audio":"敲门声、催促声、马桶冲水","character":"五位室友 — 程序员、网红、考研党、外卖员、鼓手","directorNote":"一字排开横移，夸张肢体","emotionIntensity":55},{"shotNumber":"03","shotType":"近景","visual":"冰箱贴满标签，网红女孩发现酸奶又被偷喝，怒贴第七张警告条","duration":"4s","dialogue":"（网红）这是本月第七盒！我要装监控了！","audio":"冰箱门吸合声、便利贴撕拉","character":"网红小美","directorNote":"特写满是标签的冰箱，细节笑点","emotionIntensity":50},{"shotNumber":"04","shotType":"中景","visual":"考研党戴降噪耳机刷题，隔壁鼓手疯狂排练架子鼓，墙在抖","duration":"5s","dialogue":"（考研党崩溃）拜托！我还有三十天考试！","audio":"激烈鼓点、墙体震动、哀嚎","character":"考研党阿文、鼓手大鹏","directorNote":"【第二幕·宣战】分屏对比两人，反差喜剧","emotionIntensity":60},{"shotNumber":"05","shotType":"中景","visual":"五人围着一张水电费账单激烈辩论，谁也不肯多掏一块钱","duration":"6s","dialogue":"（外卖员）我天天在外面跑，凭什么平摊电费！","audio":"七嘴八舌的争吵、拍桌","character":"五位室友","directorNote":"环绕拍摄圆桌会议，群口相声式调度","emotionIntensity":55},{"shotNumber":"06","shotType":"近景","visual":"争吵中突然全屋停电，五人黑暗里大眼瞪小眼，齐刷刷掏手机照明","duration":"4s","dialogue":"（齐声）……谁没交电费？","audio":"跳闸声、寂静、五声叹气","character":"五位室友","directorNote":"黑场仅手机光，定格尴尬","emotionIntensity":65},{"shotNumber":"07","shotType":"中景","visual":"没钱叫外卖的深夜，五人翻出各自仅剩的食材，凑了一锅黑暗料理火锅","duration":"6s","dialogue":"（鼓手）我贡献半根火腿肠！（网红）我有一包面膜……啊不是。","audio":"锅咕嘟声、哄笑","character":"五位室友","directorNote":"【第三幕·和解】暖光围炉，氛围转暖","emotionIntensity":70},{"shotNumber":"08","shotType":"近景","visual":"考研党发现，鼓手每天排练其实是想用鼓声当他复习的背景白噪音","duration":"5s","dialogue":"（鼓手挠头）你说你睡不着，我寻思鼓声催眠嘛。","audio":"轻笑、火锅咕嘟声","character":"阿文、大鹏","directorNote":"双人近景，误会化解的温情","emotionIntensity":65},{"shotNumber":"09","shotType":"中景","visual":"五人挤在小阳台吃火锅看夜景，因为停电反而聊了第一次心里话","duration":"6s","dialogue":"（小美）其实……跟你们挤这破房子，还挺好的。","audio":"城市夜风、笑声渐柔","character":"五位室友","directorNote":"阳台群像，暖黄路灯做背景","emotionIntensity":75},{"shotNumber":"10","shotType":"远景","visual":"第二天清晨，卫生间门口又排起长队，这次他们边骂边笑地递牙刷","duration":"6s","dialogue":"（旁白）所谓家人，就是一边嫌弃，一边谁也离不开谁。","audio":"熟悉的早高峰交响、笑闹","character":"五位室友","directorNote":"与开场呼应，循环式喜剧收尾","emotionIntensity":60}]'::jsonb,
